# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SÖZLÜ İLETİŞİM: HİKÂYE DRAMATİZASYONU VE YAZAR SUNUMU</text>\n  <rect x="25" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Hikâye Dramatizasyonu Aşamaları</text>\n  <text x="40" y="95" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">1. Metin Uyarlama:</tspan> Olay örgüsü ve çatışmayı</text>\n  <text x="50" y="112" font-size="11" fill="#1e3a8a">koruyarak anlatımı diyaloglara dönüştürme</text>\n  <text x="40" y="136" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">2. Rol Dağılımı:</tspan> Karakter ve tip özelliklerine</text>\n  <text x="50" y="153" font-size="11" fill="#1e3a8a">uygun kişi seçimi ve kostüm/dekor hazırlığı</text>\n  <text x="40" y="177" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">3. Sahneleme (Diksiyon &amp; Beden Dili):</tspan></text>\n  <text x="50" y="194" font-size="11" fill="#1e3a8a">Doğru boğumlama, vurgu, tonlama, jest ve mimik</text>\n  <text x="40" y="218" font-size="11" font-weight="bold" fill="#1d4ed8">Amaç: Kurmacayı görsel-işitsel yaşantıya dönüştürmek</text>\n\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Etkili Yazar Sunumu İlkeleri</text>\n  <text x="380" y="95" font-size="12" fill="#14532d">• <tspan font-weight="bold">Hazırlık:</tspan> Birincil kaynak ve eser taraması</text>\n  <text x="380" y="120" font-size="12" fill="#14532d">• <tspan font-weight="bold">Odak Noktası:</tspan> Yazarın edebi kişiliği, üslubu,</text>\n  <text x="390" y="137" font-size="11" fill="#14532d">hikâye türü (olay/durum) ve temaları</text>\n  <text x="380" y="162" font-size="12" fill="#14532d">• <tspan font-weight="bold">Sunum Tekniği:</tspan> Slaytları harfiyen okumamak,</text>\n  <text x="390" y="179" font-size="11" fill="#14532d">dinleyiciyle göz teması kurmak, süreyi yönetmek</text>\n  <text x="380" y="204" font-size="12" fill="#14532d">• <tspan font-weight="bold">Örneklem:</tspan> Yazarın bir hikâyesinden seçilen</text>\n  <text x="390" y="221" font-size="11" font-weight="bold" fill="#15803d">kısa ve etkileyici bir kesiti seslendirmek</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ANLATIM BOZUKLUKLARI: BAĞDAŞIKLIK (ANLAM) VE BAĞLAŞIKLIK (YAPI)</text>\n  <rect x="25" y="45" width="320" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="185" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">1. Anlama Dayalı (Bağdaşıklık) Kusurları</text>\n  <text x="40" y="93" font-size="11" fill="#78350f">• <tspan font-weight="bold">Gereksiz Sözcük:</tspan> "Yaklaşık üç yıl kadar çalıştı."</text>\n  <text x="40" y="114" font-size="11" fill="#78350f">• <tspan font-weight="bold">Anlamca Çelişen:</tspan> "Şüphesiz oraya gitmiş olabilir."</text>\n  <text x="40" y="135" font-size="11" fill="#78350f">• <tspan font-weight="bold">Yanlış Anlam:</tspan> "Bahçeye fidan ektik." (diktik)</text>\n  <text x="40" y="156" font-size="11" fill="#78350f">• <tspan font-weight="bold">Yanlış Yer:</tspan> "Ağrısız kulak delinir." (kulak ağrısız)</text>\n  <text x="40" y="177" font-size="11" fill="#78350f">• <tspan font-weight="bold">Deyim Yanlışı:</tspan> "Sevinçten etekleri tutuştu." (zil çaldı)</text>\n  <text x="40" y="198" font-size="11" fill="#78350f">• <tspan font-weight="bold">Anlam Belirsizliği:</tspan> "Kitabını masada gördüm." (Senin/Onun)</text>\n  <text x="40" y="219" font-size="11" fill="#78350f">• <tspan font-weight="bold">Mantık Hatası:</tspan> Önem sırasının ters verilmesi</text>\n\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">2. Yapıya Dayalı (Bağlaşıklık) Kusurları</text>\n  <text x="380" y="93" font-size="11" fill="#581c87">• <tspan font-weight="bold">Özne-Yüklem Uyumsuzluğu:</tspan> "Hiçbiri gelmedi,</text>\n  <text x="390" y="109" font-size="11" fill="#581c87">(herkes) evde bekledi."</text>\n  <text x="380" y="132" font-size="11" fill="#581c87">• <tspan font-weight="bold">Öge Eksikliği (Nesne / Tümleç):</tspan></text>\n  <text x="390" y="148" font-size="11" fill="#581c87">"Size inanıyor ve (sizi) destekliyoruz."</text>\n  <text x="380" y="171" font-size="11" fill="#581c87">• <tspan font-weight="bold">Tamlama Yanlışı:</tspan> "Kamu ve özel kuruluşlar"</text>\n  <text x="390" y="187" font-size="11" fill="#581c87">(Kamu kuruluşları ve özel kuruluşlar)</text>\n  <text x="380" y="210" font-size="11" fill="#581c87">• <tspan font-weight="bold">Çatı Uyuşmazlığı:</tspan> "Sorular çözülüp çıkıldı." (çözülüp)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">2. ÜNİTE ÖZETİ: CUMHURİYET DÖNEMİ HİKÂYE EĞİLİMLERİ</text>\n  <rect x="20" y="46" width="210" height="192" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">Toplumcu &amp; Durum Hikâyesi</text>\n  <text x="32" y="92" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Toplumcu Gerçekçiler:</tspan></text>\n  <text x="40" y="108" font-size="10" fill="#0c4a6e">Sabahattin Ali, Sadri Ertem, Orhan</text>\n  <text x="40" y="122" font-size="10" fill="#0c4a6e">Kemal, Kemal Tahir, Yaşar Kemal,</text>\n  <text x="40" y="136" font-size="10" fill="#0c4a6e">Samim Kocagöz, Fakir Baykurt</text>\n  <text x="32" y="160" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Çehov (Durum) Öncüleri:</tspan></text>\n  <text x="40" y="176" font-size="10" fill="#0c4a6e">Memduh Şevket Esendal,</text>\n  <text x="40" y="190" font-size="10" fill="#0c4a6e">Sait Faik Abasıyanık</text>\n  <text x="32" y="214" font-size="10" font-weight="bold" fill="#0369a1">Köy-kent, işçi-işveren, yaşama sevinci</text>\n\n  <rect x="245" y="46" width="210" height="192" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Bireyin İç Dünyası &amp; Millî-Dinî</text>\n  <text x="257" y="92" font-size="11" fill="#14532d">• <tspan font-weight="bold">Bireyin İç Dünyası:</tspan></text>\n  <text x="265" y="108" font-size="10" fill="#14532d">Peyami Safa, A. Hamdi Tanpınar,</text>\n  <text x="265" y="122" font-size="10" fill="#14532d">Tarık Buğra, Samiha Ayverdi,</text>\n  <text x="265" y="136" font-size="10" fill="#14532d">Haldun Taner, Oktay Akbal</text>\n  <text x="257" y="160" font-size="11" fill="#14532d">• <tspan font-weight="bold">Millî ve Dinî Duyarlılık:</tspan></text>\n  <text x="265" y="176" font-size="10" fill="#14532d">Mustafa Kutlu, Rasim Özdenören,</text>\n  <text x="265" y="190" font-size="10" fill="#14532d">Sevinç Çokum, Hüseyin Nihal Atsız</text>\n  <text x="257" y="214" font-size="10" font-weight="bold" fill="#15803d">Psikoloji, yabancılaşma, gelenek-modern</text>\n\n  <rect x="470" y="46" width="210" height="192" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Modernist &amp; Küçürek Hikâye</text>\n  <text x="482" y="92" font-size="11" fill="#78350f">• <tspan font-weight="bold">Modernist / Postmodernist:</tspan></text>\n  <text x="490" y="108" font-size="10" fill="#78350f">Oğuz Atay, Yusuf Atılgan, Ferit Edgü,</text>\n  <text x="490" y="122" font-size="10" fill="#78350f">Adalet Ağaoğlu, Bilge Karasu,</text>\n  <text x="490" y="136" font-size="10" fill="#78350f">Vüs\'at O. Bener, Nezihe Meriç</text>\n  <text x="482" y="160" font-size="11" fill="#78350f">• <tspan font-weight="bold">Küçürek (Minimal) Hikâye:</tspan></text>\n  <text x="490" y="176" font-size="10" fill="#78350f">Ferit Edgü, Necati Tosuner, Hulki</text>\n  <text x="490" y="190" font-size="10" fill="#78350f">Aktunç (Az sözle yoğun imgesel anlam)</text>\n  <text x="482" y="214" font-size="10" font-weight="bold" fill="#b45309">Teknikler: Bilinç akışı, iç çözümleme</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
